from pathlib import Path
text = Path('assets/uploads/5c66efd3_【20260305大组会】工作文档.md').read_text(encoding='utf-8')
print('len', len(text))
# print headings and lines with target keywords
keywords = ['Ce', 'Co3O4', '亚氯酸盐', 'PMSO', 'pmso', 'EPR', 'epr', 'XPS', 'xps', 'XRD', 'xrd', '组会', '工作安排', '进度', '论文', '实验', '图']
lines = text.splitlines()
for i, line in enumerate(lines, 1):
    if line.strip().startswith('#'):
        print(f'H{i}: {line.strip()}')
print('\nKEYWORD HITS:')
for i, line in enumerate(lines, 1):
    if any(k.lower() in line.lower() for k in keywords):
        print(f'{i}: {line[:180]}')
